#include <iostream>
#include <queue>
#include <cstring>
#include <vector>
#include <algorithm>
using namespace std;

const int MAXN = 15;
const int MAXM = 100005;
const int INF = 1e9;

int n, T;
char grid[MAXN][MAXN], target[MAXN][MAXN];
int id[MAXN][MAXN], total;
int distStart[MAXN][MAXN], distTarget[MAXN][MAXN];

struct Edge {
    int to, cap, flow;
    Edge(int t, int c) : to(t), cap(c), flow(0) {}
};

vector<Edge> edgeList;
vector<int> adj[3005];

void addEdge(int u, int v, int cap) {
    adj[u].push_back(edgeList.size());
    edgeList.emplace_back(v, cap);
    adj[v].push_back(edgeList.size());
    edgeList.emplace_back(u, 0);
}

bool bfs(int sx, int sy, int dist[][MAXN]) {
    queue<pair<int, int>> q;
    memset(dist, 0x3f, sizeof(int) * MAXN * MAXN);
    if (sx >= 0 && sx < n && sy >= 0 && sy < n && grid[sx][sy] != '#') {
        dist[sx][sy] = 0;
        q.push({sx, sy});
    }
    const int dx[] = {0, 0, -1, 1};
    const int dy[] = {1, -1, 0, 0};
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int i = 0; i < 4; ++i) {
            int nx = x + dx[i], ny = y + dy[i];
            if (nx >= 0 && nx < n && ny >= 0 && ny < n &&
                grid[nx][ny] >= '0' && grid[nx][ny] <= '9' &&
                dist[nx][ny] > dist[x][y] + 1) {
                dist[nx][ny] = dist[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
    return true;
}

bool level[3005];
int current[3005];

bool buildLevelGraph() {
    memset(level, 0, sizeof(level));
    queue<int> q;
    q.push(2 * total + 1);
    level[2 * total + 1] = true;
    current[2 * total + 1] = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int idx : adj[u]) {
            auto& e = edgeList[idx];
            if (!level[e.to] && e.cap > e.flow) {
                level[e.to] = true;
                current[e.to] = 0;
                q.push(e.to);
            }
        }
    }
    return level[2 * total + 2];
}

int dfs(int u, int flow) {
    if (u == 2 * total + 2 || flow == 0) return flow;
    for (int& i = current[u]; i < (int)adj[u].size(); ++i) {
        int idx = adj[u][i];
        auto& e = edgeList[idx];
        if (level[e.to] && e.cap > e.flow) {
            int pushed = dfs(e.to, min(flow, e.cap - e.flow));
            if (pushed > 0) {
                e.flow += pushed;
                edgeList[idx ^ 1].flow -= pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int dinic() {
    int flow = 0;
    while (buildLevelGraph()) {
        int pushed;
        while ((pushed = dfs(2 * total + 1, INF)) > 0) {
            flow += pushed;
        }
    }
    return flow;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> T;
    for (int i = 0; i < n; ++i) cin >> grid[i];
    for (int i = 0; i < n; ++i) cin >> target[i];

    int sx = -1, sy = -1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 'Z') {
                sx = i; sy = j;
                grid[i][j] = '0';
            }
            id[i][j] = ++total;
        }
    }

    bfs(sx, sy, distStart);

    const int source = 2 * total + 1;
    const int sink = source + 1;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] >= '1' && grid[i][j] <= '9') {
                addEdge(source, id[i][j], grid[i][j] - '0');
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (target[i][j] >= '1' && target[i][j] <= '9') {
                addEdge(id[i][j] + total, sink, target[i][j] - '0');
            }
        }
    }

    const int dx[] = {0, 0, -1, 1};
    const int dy[] = {1, -1, 0, 0};

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] >= '1' && grid[i][j] <= '9') {
                int dist[MAXN][MAXN];
                memset(dist, 0x3f, sizeof(dist));
                queue<pair<int, int>> q;
                dist[i][j] = 0;
                q.push({i, j});
                while (!q.empty()) {
                    auto [x, y] = q.front(); q.pop();
                    for (int k = 0; k < 4; ++k) {
                        int nx = x + dx[k], ny = y + dy[k];
                        if (nx >= 0 && nx < n && ny >= 0 && ny < n &&
                            grid[nx][ny] >= '0' && grid[nx][ny] <= '9' &&
                            dist[nx][ny] > dist[x][y] + 1) {
                            dist[nx][ny] = dist[x][y] + 1;
                            q.push({nx, ny});
                        }
                    }
                }
                for (int x = 0; x < n; ++x) {
                    for (int y = 0; y < n; ++y) {
                        if (target[x][y] >= '1' && target[x][y] <= '9' &&
                            dist[x][y] <= T && dist[x][y] <= distStart[x][y]) {
                            addEdge(id[i][j], id[x][y] + total, INF);
                        }
                    }
                }
            }
        }
    }

    cout << dinic() << '\n';
    return 0;
}
